//! Terrain-diffusion worlds take their shape and biomes from region files
//! pre-generated by ironore's pomme-terrain, one per 512 by 512 blocks.
//!
//! `r.<rx>.<rz>.tdr` covers blocks x from `rx * 512` and z from `rz * 512`.
//! It is `TDR1`, a byte with the world's scale, then a zstd frame holding
//! each column's first air y as 512 * 512 little-endian i16, then its biome
//! as 512 * 512 bytes indexing [`BIOMES`], both row by row along z.

use std::collections::VecDeque;
use std::io::Read;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};

use pumpkin_data::biome::Biome;
use rustc_hash::FxHashMap;

const REGION_BLOCKS: i32 = 512;
const COLUMNS: usize = (REGION_BLOCKS * REGION_BLOCKS) as usize;
/// Regions kept decoded, about 0.75 MiB each.
const CACHED_REGIONS: usize = 64;

/// The biomes a region file names, in pomme-terrain's order.
const BIOMES: [&Biome; 20] = [
    &Biome::PLAINS,
    &Biome::SNOWY_PLAINS,
    &Biome::DESERT,
    &Biome::SWAMP,
    &Biome::FOREST,
    &Biome::TAIGA,
    &Biome::SNOWY_TAIGA,
    &Biome::SAVANNA,
    &Biome::WINDSWEPT_HILLS,
    &Biome::JUNGLE,
    &Biome::BADLANDS,
    &Biome::MEADOW,
    &Biome::GROVE,
    &Biome::SNOWY_SLOPES,
    &Biome::FROZEN_PEAKS,
    &Biome::STONY_PEAKS,
    &Biome::WARM_OCEAN,
    &Biome::OCEAN,
    &Biome::COLD_OCEAN,
    &Biome::FROZEN_OCEAN,
];

struct Region {
    top: Box<[i16]>,
    biome: Box<[u8]>,
}

#[derive(Default)]
struct Cache {
    regions: FxHashMap<(i32, i32), Arc<Region>>,
    order: VecDeque<(i32, i32)>,
}

/// The pre-generated heightmap and biomes of one world.
pub struct DiffusionTerrain {
    dir: PathBuf,
    scale: u8,
    cache: Mutex<Cache>,
}

impl DiffusionTerrain {
    #[must_use]
    pub fn new(dir: PathBuf, scale: u8) -> Self {
        Self {
            dir,
            scale,
            cache: Mutex::default(),
        }
    }

    /// The first air y of the column at block `x`, `z`: blocks below it are
    /// terrain.
    #[must_use]
    pub fn top(&self, x: i32, z: i32) -> i32 {
        let (region, index) = self.locate(x, z);
        i32::from(region.top[index])
    }

    #[must_use]
    pub fn biome(&self, x: i32, z: i32) -> &'static Biome {
        let (region, index) = self.locate(x, z);
        BIOMES[usize::from(region.biome[index])]
    }

    /// The nearest dry column to the origin, searched outwards in rings of
    /// 16 blocks to 2,048 blocks out, standing on its surface.
    #[must_use]
    pub fn find_land(&self, sea_level: i32) -> pumpkin_util::math::position::BlockPos {
        for ring in 0..=128 {
            let r = ring * 16;
            for step in -ring..=ring {
                let s = step * 16;
                for (x, z) in [(s, -r), (s, r), (-r, s), (r, s)] {
                    let top = self.top(x, z);
                    if top > sea_level + 1 {
                        return pumpkin_util::math::position::BlockPos::new(x, top, z);
                    }
                }
            }
        }
        pumpkin_util::math::position::BlockPos::new(0, self.top(0, 0).max(sea_level + 1), 0)
    }

    fn locate(&self, x: i32, z: i32) -> (Arc<Region>, usize) {
        let key = (x.div_euclid(REGION_BLOCKS), z.div_euclid(REGION_BLOCKS));
        let index = (z.rem_euclid(REGION_BLOCKS) * REGION_BLOCKS + x.rem_euclid(REGION_BLOCKS)) as usize;
        let mut cache = self
            .cache
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(region) = cache.regions.get(&key) {
            return (region.clone(), index);
        }
        let region = Arc::new(self.read(key));
        if cache.order.len() == CACHED_REGIONS
            && let Some(oldest) = cache.order.pop_front()
        {
            cache.regions.remove(&oldest);
        }
        cache.order.push_back(key);
        cache.regions.insert(key, region.clone());
        (region, index)
    }

    /// Reads a region. Generating outside the pre-generated disc, or from a
    /// damaged file, fails the chunk loudly: there is no other terrain.
    #[expect(clippy::panic, reason = "a terrain-diffusion world has no fallback terrain")]
    fn read(&self, (rx, rz): (i32, i32)) -> Region {
        let path = self.dir.join(format!("r.{rx}.{rz}.tdr"));
        let bytes = std::fs::read(&path).unwrap_or_else(|error| {
            panic!(
                "terrain-diffusion region {} is missing ({error}): the world was pre-generated over a smaller disc",
                path.display()
            )
        });
        assert!(
            bytes.len() > 5 && &bytes[..4] == b"TDR1",
            "{} is not a terrain-diffusion region",
            path.display()
        );
        assert!(
            bytes[4] == self.scale,
            "{} was generated at scale {}, the world is scale {}",
            path.display(),
            bytes[4],
            self.scale
        );
        let mut payload = Vec::with_capacity(3 * COLUMNS);
        ruzstd::decoding::StreamingDecoder::new(&bytes[5..])
            .unwrap_or_else(|error| panic!("{} is damaged: {error}", path.display()))
            .read_to_end(&mut payload)
            .unwrap_or_else(|error| panic!("{} is damaged: {error}", path.display()));
        assert!(payload.len() == 3 * COLUMNS, "{} is short", path.display());
        let top = payload[..2 * COLUMNS]
            .chunks_exact(2)
            .map(|b| i16::from_le_bytes([b[0], b[1]]))
            .collect();
        let biome: Box<[u8]> = payload[2 * COLUMNS..].into();
        assert!(
            biome.iter().all(|&b| usize::from(b) < BIOMES.len()),
            "{} names an unknown biome",
            path.display()
        );
        Region { top, biome }
    }
}
